fn is_odd_at_odd_index(arr: &Vec<usize>) -> bool {
    // Check each element in the array
    for (index, &value) in arr.iter().enumerate() {
        // Check if the parity of index and value match
        // Even index should have even value, odd index should have odd value
        if (index % 2 == 0 && value % 2 != 0) || (index % 2 != 0 && value % 2 == 0) {
            return false;
        }
    }
    true
}

